public class ConsistentHash<T>
{
    private readonly SortedList<long, T> _ring = new();
    private readonly int _vNodes;
    private readonly IHasher _hasher;

    public ConsistentHash(IEnumerable<T> nodes, int virtualNodes = 150)
    {
        _vNodes = virtualNodes;
        _hasher = new Murmur3();
        foreach (var node in nodes) AddNode(node);
    }

    public void AddNode(T node)
    {
        for (int i = 0; i < _vNodes; i++)
        {
            var key = _hasher.Hash(ComputeVNodeKey(node, i));
            _ring[key] = node;        // store physical node at vnode position
        }
    }

    public T GetNode(string key)
    {
        if (_ring.Count == 0) return default!;
        var h = _hasher.Hash(key);

        // Find the first vnode position >= h (lower-bound / ceiling)
        var idx = _ring.Keys.ToList().BinarySearch(h);
        if (idx < 0) idx = ~idx;                // bitwise complement = insertion point
        if (idx == _ring.Count) idx = 0;       // wrap around the ring

        return _ring[_ring.Keys[idx]];
    }

    // Return next N distinct physical nodes for replication
    public IReadOnlyList<T> GetNodes(string key, int count)
    {
        var result = new HashSet<T>();
        if (_ring.Count == 0) return result.ToList();
        var h = _hasher.Hash(key);
        var idx = LowerBound(h);               // first >= h

        var physicalCount = CountDistinct();
        count = Math.Min(count, physicalCount);

        while (result.Count < count)
        {
            var vnodeKey = _ring.Keys[idx % _ring.Count];
            result.Add(_ring[vnodeKey]);
            idx++;
        }
        return result.ToList();
    }
}
